const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const M = data[1];

const colSum = new Array(M).fill(0);

let idx = 2;
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    colSum[j] += data[idx++];
  }
}

let min = Infinity;
for (let j = 0; j < M; j++) {
  if (colSum[j] < min) min = colSum[j];
}

console.log(min);
